Lemma rec_upd st g f x :
  get_meta_rec (upd_meta g f st) x = if aptr_eqb x g then f (get_meta_rec st g) else get_meta_rec st x.
Proof.
ltac2:(KReplay.run1 (kr_t_MallocFacts_Bpres ()) ["CEIL_WRAP_3"] "h01fh11gh22sth31xp;4g00Vbj40Tg00X@R0g005OR1g00YRR2P2[R2f3R3f2R4f1R5f0R6C0X31X02X11X20P3P4P5P6O4X31W0W1W2o"). Qed.

Lemma rec_put st g mr x :
  get_meta_rec (put_meta g mr st) x = if aptr_eqb x g then mr else get_meta_rec st x.
Proof.
ltac2:(KReplay.run1 (kr_t_MallocFacts_Bpres ()) ["CEIL_WRAP_3"] "h01gh12mrh22sth31xp;4g00Zbj40Tg00X@R0g005OR1g00YRR2f3R3f2R4f1R5f0R6C0X31X12X01X20P3P4P5P6O4X31W1W0W2o"). Qed.

