Lemma KINV_queue : forall st LB c g p sc,
  KINV st LB c -> hosts st p g -> sc = m_sizeclass (get_meta_rec st g) -> 0 <= sc < 48 ->
  m_next (get_meta_rec st g) = None -> m_prev (get_meta_rec st g) = None ->
  active st sc <> Some g ->
  KINV (queue_st (LActive sc) g st) LB c.
Proof.
