  KINV st LB c -> LPRE st LB c g p i -> m_maplen (get_meta_rec st g) <> 0 ->
  (forall j, 0 <= j <= m_last_idx (get_meta_rec st g) -> j <> i -> slot_free (get_meta_rec st g) j) ->
  forall b gh, (s_groups st) !! b = Some gh -> fst b = fst p -> b = p.
